-- LipaByte sample listings seed (~500 items)
-- InfinityFree: select YOUR database in phpMyAdmin left sidebar, then run this.
-- DO NOT use USE lipabyte_db;

SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';
SET time_zone = '+08:00';

-- Clear old sample listings (keeps users/categories). Adjust IDs if needed.
DELETE FROM `listing_images` WHERE `listing_id` > 9;
DELETE FROM `rental_requests` WHERE `listing_id` > 9;
DELETE FROM `listings` WHERE `listing_id` > 9;


